CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "Account" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,"cash" BIGINT NOT NULL DEFAULT 100000000 CHECK ("cash">=0));
CREATE TABLE "Instrument" ("symbol" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"exchange" TEXT NOT NULL,"sector" TEXT NOT NULL,"price" BIGINT NOT NULL CHECK ("price">0),"previousClose" BIGINT NOT NULL CHECK ("previousClose">0),"metrics" JSONB NOT NULL);
CREATE INDEX "Instrument_exchange_sector_idx" ON "Instrument"("exchange","sector");
CREATE TABLE "PriceHistory" ("id" TEXT PRIMARY KEY,"symbol" TEXT NOT NULL REFERENCES "Instrument"("symbol") ON DELETE CASCADE,"time" TIMESTAMP(3) NOT NULL,"open" BIGINT NOT NULL,"high" BIGINT NOT NULL,"low" BIGINT NOT NULL,"close" BIGINT NOT NULL,"volume" INTEGER NOT NULL,CHECK("low"<=LEAST("open","close") AND "high">=GREATEST("open","close") AND "volume">=0),UNIQUE("symbol","time"));
CREATE TABLE "Watchlist" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,UNIQUE("userId","name"));
CREATE TABLE "WatchlistItem" ("id" TEXT PRIMARY KEY,"watchlistId" TEXT NOT NULL REFERENCES "Watchlist"("id") ON DELETE CASCADE,"symbol" TEXT NOT NULL REFERENCES "Instrument"("symbol"),UNIQUE("watchlistId","symbol"));
CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id"),"symbol" TEXT NOT NULL REFERENCES "Instrument"("symbol"),"side" TEXT NOT NULL CHECK("side" IN ('BUY','SELL')),"type" TEXT NOT NULL CHECK("type" IN ('MARKET','LIMIT','STOP_LOSS')),"quantity" INTEGER NOT NULL CHECK("quantity">0),"triggerPrice" BIGINT CHECK("triggerPrice">0),"status" TEXT NOT NULL CHECK("status" IN ('PENDING','FILLED','CANCELLED','REJECTED')),"reason" TEXT,"idempotencyKey" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","idempotencyKey"));
CREATE INDEX "Order_userId_createdAt_idx" ON "Order"("userId","createdAt");
CREATE INDEX "Order_userId_status_idx" ON "Order"("userId","status");
CREATE TABLE "Execution" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL UNIQUE REFERENCES "Order"("id"),"price" BIGINT NOT NULL CHECK("price">0),"quantity" INTEGER NOT NULL CHECK("quantity">0),"notional" BIGINT NOT NULL CHECK("notional">0),"fee" BIGINT NOT NULL CHECK("fee">=0),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Position" ("id" TEXT PRIMARY KEY,"accountId" TEXT NOT NULL REFERENCES "Account"("id"),"symbol" TEXT NOT NULL REFERENCES "Instrument"("symbol"),"quantity" INTEGER NOT NULL CHECK("quantity">=0),"costBasis" BIGINT NOT NULL CHECK("costBasis">=0),"realizedGross" BIGINT NOT NULL DEFAULT 0,"fees" BIGINT NOT NULL DEFAULT 0,UNIQUE("accountId","symbol"));
CREATE TABLE "CashLedger" ("id" TEXT PRIMARY KEY,"accountId" TEXT NOT NULL REFERENCES "Account"("id"),"executionId" TEXT UNIQUE REFERENCES "Execution"("id"),"kind" TEXT NOT NULL,"delta" BIGINT NOT NULL,"balanceAfter" BIGINT NOT NULL CHECK("balanceAfter">=0),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "CashLedger_accountId_createdAt_idx" ON "CashLedger"("accountId","createdAt");
CREATE TABLE "Trade" ("id" TEXT PRIMARY KEY,"executionId" TEXT NOT NULL UNIQUE REFERENCES "Execution"("id"),"realizedGross" BIGINT NOT NULL,"removedBasis" BIGINT NOT NULL);
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"message" TEXT NOT NULL,"read" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Notification_userId_createdAt_idx" ON "Notification"("userId","createdAt");
CREATE TABLE "PriceAlert" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"symbol" TEXT NOT NULL REFERENCES "Instrument"("symbol"),"target" BIGINT NOT NULL CHECK("target">0),"direction" TEXT NOT NULL CHECK("direction" IN ('ABOVE','BELOW')),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PriceAlert_userId_idx" ON "PriceAlert"("userId");
CREATE TABLE "RateLimit" ("key" TEXT PRIMARY KEY,"count" INTEGER NOT NULL,"resetAt" TIMESTAMP(3) NOT NULL);
